// Merge extracted fields with the original paper payload so identifiers
// and metadata survive into downstream validation/storage workflows.
const modelItems = $input.all();
const originalItems = $('When Called by Ingestion').all();
const results = [];

for (let i = 0; i < modelItems.length; i++) {
  const item = modelItems[i];
  const original = (originalItems[i] && originalItems[i].json) ? originalItems[i].json : {};

  const out = item.json.output;
  let extracted = {};

  if (Array.isArray(out) && out[0] && Array.isArray(out[0].content) && out[0].content[0]) {
    const t = out[0].content[0].text;
    if (typeof t === 'string') {
      try {
        extracted = JSON.parse(t);
      } catch (e) {
        extracted = {};
      }
    } else if (t && typeof t === 'object') {
      extracted = t;
    }
  }

  results.push({
    json: {
      ...original,
      ...extracted,
    },
  });
}

return results;
